import assert from "node:assert/strict";
import {execFileSync} from "node:child_process";
import test from "node:test";

const replay = (capture) => {
  const args = ["operations/retest.mjs"];
  if (capture) args.push(capture);
  return JSON.parse(
    execFileSync(process.execPath, args, {
      cwd: new URL("..", import.meta.url),
      encoding: "utf8",
    }),
  );
};

test("revised sheet is exact under the later DUTY-2340 capture", () => {
  const result = replay();

  assert.equal(result.run, "DUTY-2340");
  assert.deepEqual(result.limits, [80, 40, 50, 70]);
  assert.deepEqual(result.actual, [80, 40, 50, 70]);
  assert.deepEqual(result.departureKwh, [126, 130]);
  assert.deepEqual(result.marginsKwh, [0, 0]);
  assert.equal(result.withinLimits, true);
});

test("earlier DESK-21 capture is incompatible with the same fixed sheet", () => {
  const result = replay("operations/cold-cycle.json");

  assert.equal(result.run, "DESK-21");
  assert.deepEqual(result.limits, [80, 40, 70, 50]);
  assert.deepEqual(result.actual, [80, 40, 50, 50]);
  assert.deepEqual(result.departureKwh, [126, 121]);
  assert.deepEqual(result.marginsKwh, [0, -9]);
  assert.equal(result.withinLimits, false);
});
